"""Experimento B pelo CEMADEN: hora do pico de chuva por distrito (carga --refazer), tabela e experimento."""
import sys
from pathlib import Path

if not Path("ml/experimento_mare.py").exists():
    sys.exit("Aplique antes o aplicar_experimento_mare.py.")
if "hora_pico_utc" in Path("etl/historico/cemaden.py").read_text(encoding="utf-8"):
    sys.exit("Já aplicado.")

ARQUIVOS = {
    'etl/derivados/ml_distrito_dia.py': '"""Tabela do modelo de risco: uma linha por distrito e dia, 2014-2024 (etapa 3e).\n\nJunta tudo o que foi carregado na etapa 3:\n  chuva   CEMADEN por pluviômetro (pior estação do distrito); se o distrito não\n          tem estação válida no dia, a estação do INMET (A301) como chuva da cidade\n  maré    maré astronômica calculada (máxima e amplitude do dia)\n  alvo    atendimentos da Defesa Civil LIGADOS À CHUVA no distrito, no dia (decisão 009)\n  contexto  mês, dia da semana, feriado, pandemia, vulnerabilidade do distrito\n\n  gold  gold.ml_distrito_dia\n\nConvenção de tempo (decisão 009): a chuva "do dia" é a do próprio dia D. No uso\ndiário ela vem da PREVISÃO para amanhã; no treino, da chuva medida (previsão\nperfeita, o que deixa a avaliação otimista e precisa constar no relatório).\nO "dia crítico" (p95 do distrito) NÃO é calculado aqui: depende do período de\ntreino e é feito no treino, para não vazar informação do teste.\n\nUso:\n    python -m etl.derivados.ml_distrito_dia\n"""\n\nfrom collections import defaultdict\nfrom datetime import date, datetime, timedelta, timezone\n\nfrom shapely.geometry import Point\n\nfrom dominio.bairros import APELIDOS_PLANO\nfrom dominio.distritos import nome_distrito\nfrom dominio.feriados import feriados_recife\nfrom etl.comum.distritos import distrito_de, distritos_poligonos\nfrom etl.comum.texto import normalizar\nfrom etl.destinos import obter_destino\nfrom etl.destinos.base import Carga\n\nINICIO, FIM = date(2014, 1, 1), date(2024, 12, 31)\nMIN_LEITURAS = 20       # estação-dia com menos leituras que isso é "sem dado", não "sem chuva"\nMIN_HORAS_INMET = 20\nPANDEMIA = (date(2020, 3, 18), date(2021, 12, 31))\n# separação do alvo por tipo de evento: a maré só pesa no alagamento (planície)\nTERMOS_ALAGAMENTO = ("ALAGA", "INUNDA")\nTERMOS_DESLIZAMENTO = ("DESLIZ", "BARREIRA")\n# nomes da Defesa Civil que não são bairros do IBGE (1% dos atendimentos, ver dias_criticos.py)\nAPELIDOS_DC = {**{k: v[0] for k, v in APELIDOS_PLANO.items()}, "BAIRRO DO RECIFE": "RECIFE", "POCO DA PANELA": "POCO"}\nCOLECAO_COORD = "silver_estacoes_historico"\n\n\n# ── coordenadas das estações (as paradas hoje não têm coordenada no cadastro diário) ──\ndef ler_coordenada(texto):\n    """(lat, lon) da primeira leitura de um CSV do CEMADEN; None se vazio."""\n    from etl.comum.cemaden import ler_serie\n    for l in ler_serie(texto):\n        try:\n            return float(l["latitude"].replace(",", ".")), float(l["longitude"].replace(",", "."))\n        except (KeyError, ValueError, AttributeError):\n            continue\n    return None\n\n\ndef garantir_coordenadas(banco, cliente=None, poligonos=None, avisar=print):\n    """{codestacao: distrito}. Busca na API só as estações ainda sem coordenada guardada."""\n    from etl.historico.cemaden import UF, janela_do_mes\n    conhecidas = {e["codestacao"]: e for e in banco[COLECAO_COORD].find()}\n    meses_com_dado = {}\n    for c in banco["controle_historico"].find({"fonte": "cemaden", "status": "ok", "dias": {"$gt": 0}}):\n        meses_com_dado.setdefault(c["codestacao"], c["mes"])\n    faltando = [e for e in meses_com_dado if e not in conhecidas]\n    if faltando:\n        from etl.comum.cemaden import ClienteCemaden\n        cliente = cliente or ClienteCemaden()\n        poligonos = poligonos or distritos_poligonos()\n        avisar(f"  buscando a coordenada de {len(faltando)} estações...")\n        for cod in faltando:\n            ano, mes = map(int, meses_com_dado[cod].split("-"))\n            coord = ler_coordenada(cliente.serie_csv(cod, UF, *janela_do_mes(ano, mes)))\n            if coord:\n                distrito = distrito_de(Point(coord[1], coord[0]), poligonos)\n                banco[COLECAO_COORD].update_one({"codestacao": cod}, {"$set": {\n                    "latitude": coord[0], "longitude": coord[1], "distrito_codigo": distrito}}, upsert=True)\n                conhecidas[cod] = {"distrito_codigo": distrito}\n    return {cod: e["distrito_codigo"] for cod, e in conhecidas.items()}\n\n\n# ── montagem ─────────────────────────────────────────────────────────\ndef _soma(serie, dia, dias):\n    """Soma de `dias` dias terminando em `dia`; None se faltar algum."""\n    valores = [serie.get(dia - timedelta(n)) for n in range(dias)]\n    return None if any(v is None for v in valores) else round(sum(valores), 1)\n\n\ndef montar(estacao_dia, distrito_estacao, inmet_dia, mare_dia, alvo_dia, contexto, inicio=INICIO, fim=FIM):\n    """Linhas da tabela. Entradas (todas com chaves date):\n      estacao_dia      {(codestacao, dia): (chuva_mm, max_hora_mm, leituras)}\n      distrito_estacao {codestacao: distrito}\n      inmet_dia        {dia: (chuva_mm, max_hora_mm, horas)}\n      mare_dia         {dia: (mare_max_m, amplitude_m)}\n      alvo_dia         {(distrito, dia): (chuva, reativos, alagamento, deslizamento)}\n      contexto         {distrito: {...variáveis fixas do distrito...}}\n    """\n    # 1. chuva por distrito e dia: a pior estação válida; senão o INMET\n    pior, pico = {}, {}\n    for (cod, dia), valores in estacao_dia.items():\n        mm, max_h, leituras = valores[:3]\n        hora_pico = valores[3] if len(valores) > 3 else None\n        distrito = distrito_estacao.get(cod)\n        if distrito is None or leituras < MIN_LEITURAS:\n            continue\n        atual = pior.get((distrito, dia))\n        if atual is None or mm > atual[0]:\n            pior[(distrito, dia)] = (mm, max_h, cod)\n        # a hora mais forte do distrito: a da estação com a maior chuva numa hora\n        if hora_pico is not None and max_h > 0 and max_h > pico.get((distrito, dia), (0, None))[0]:\n            pico[(distrito, dia)] = (max_h, hora_pico)\n\n    feriados = {}\n    for ano in range(inicio.year, fim.year + 1):\n        feriados.update(feriados_recife(ano))\n\n    linhas = []\n    for distrito in range(1, 9):\n        chuva, max_hora, origem = {}, {}, {}\n        d = inicio - timedelta(days=7)\n        while d <= fim:\n            if (distrito, d) in pior:\n                chuva[d], max_hora[d], origem[d] = pior[(distrito, d)][0], pior[(distrito, d)][1], "cemaden"\n            elif d in inmet_dia and inmet_dia[d][2] >= MIN_HORAS_INMET:\n                chuva[d], max_hora[d], origem[d] = inmet_dia[d][0], inmet_dia[d][1], "inmet"\n            d += timedelta(1)\n        d = inicio\n        while d <= fim:\n            alvo, reativos, alagamento, deslizamento = (tuple(alvo_dia.get((distrito, d), ())) + (0, 0, 0, 0))[:4]\n            mare = mare_dia.get(d, (None, None))\n            linhas.append({\n                "distrito_codigo": distrito, "distrito": nome_distrito(distrito),\n                "data": datetime(d.year, d.month, d.day), "ano": d.year, "mes": d.month,\n                "dia_semana": d.weekday(), "fim_de_semana": d.weekday() >= 5,\n                "feriado": d in feriados, "pandemia": PANDEMIA[0] <= d <= PANDEMIA[1],\n                "chuva_dia_mm": chuva.get(d), "chuva_vespera_mm": chuva.get(d - timedelta(1)),\n                "chuva_3d_mm": _soma(chuva, d, 3), "chuva_7d_mm": _soma(chuva, d, 7),\n                "max_hora_mm": max_hora.get(d), "fonte_chuva": origem.get(d),\n                "chuva_pico_mm": pico.get((distrito, d), (None, None))[0],\n                "hora_pico_utc": pico.get((distrito, d), (None, None))[1],\n                "mare_max_m": mare[0], "mare_amplitude_m": mare[1],\n                **contexto.get(distrito, {}),\n                "atendimentos_chuva": alvo, "atendimentos_reativos": reativos,\n                "atendimentos_alagamento": alagamento, "atendimentos_deslizamento": deslizamento,\n            })\n            d += timedelta(1)\n    return linhas\n\n\ndef contexto_dos_distritos(banco):\n    """Variáveis fixas de cada distrito: população, comunidades e áreas de risco."""\n    distrito_do_bairro, pop = {}, defaultdict(int)\n    for b in banco["silver_bairros"].find({}, {"chave": 1, "distrito_codigo": 1, "populacao": 1}):\n        distrito_do_bairro[b["chave"]] = b.get("distrito_codigo")\n        pop[b.get("distrito_codigo")] += b.get("populacao") or 0\n    comunidades, alag, desliz = defaultdict(int), defaultdict(int), defaultdict(int)\n    for c in banco["silver_comunidades"].find({}, {"chave_bairro": 1}):\n        comunidades[distrito_do_bairro.get(c.get("chave_bairro"))] += 1\n    for a in banco["silver_areas_risco"].find({}, {"chave": 1, "alagamento": 1, "deslizamento": 1}):\n        distrito = distrito_do_bairro.get(a.get("chave"))\n        alag[distrito] += len(a.get("alagamento") or [])\n        desliz[distrito] += len(a.get("deslizamento") or [])\n    return {d: {"populacao": pop[d], "comunidades": comunidades[d], "areas_risco_alagamento": alag[d],\n                "areas_risco_deslizamento": desliz[d]} for d in range(1, 9)}\n\n\ndef ler_entradas(banco, distrito_estacao):\n    estacao_dia = {(e["codestacao"], e["data"].date()): (e["chuva_mm"], e["max_hora_mm"], e["leituras"],\n                                                          e.get("hora_pico_utc"))\n                   for e in banco["silver_chuva_estacao_dia"].find()}\n    inmet_dia = {e["data"].date(): (e["chuva_mm"], e["max_hora_mm"], e["horas_com_dado"])\n                 for e in banco["silver_chuva_inmet_dia"].find()}\n    mare_dia = {m["data"].date(): (m["mare_max_m"], m["amplitude_m"]) for m in banco["silver_mare_calculada_dia"].find()}\n    distrito_do_bairro = {b["chave"]: b.get("distrito_codigo") for b in banco["silver_bairros"].find({}, {"chave": 1, "distrito_codigo": 1})}\n    alvo = defaultdict(lambda: [0, 0, 0, 0])\n    for d in banco["silver_defesa_civil_bairro_dia"].find({}, {"data": 1, "bairro": 1, "chuva": 1, "reativos": 1,\n                                                              "por_tipo": 1, "por_ocorrencia": 1}):\n        bairro = normalizar(d["bairro"])\n        distrito = distrito_do_bairro.get(APELIDOS_DC.get(bairro, bairro))\n        if distrito:\n            a = alvo[(distrito, d["data"].date())]\n            a[0] += d.get("chuva") or 0\n            a[1] += d.get("reativos") or 0\n            tipos = list((d.get("por_tipo") or {}).items()) + list((d.get("por_ocorrencia") or {}).items())\n            a[2] += sum(n for t, n in tipos if any(x in t for x in TERMOS_ALAGAMENTO))\n            a[3] += sum(n for t, n in tipos if any(x in t for x in TERMOS_DESLIZAMENTO))\n    if not estacao_dia:\n        raise ValueError("silver_chuva_estacao_dia vazia: rode antes python -m etl.historico.cemaden")\n    if not any(a[0] for a in alvo.values()):\n        raise ValueError("a Defesa Civil não tem o campo \'chuva\': rode python -m etl defesa_civil com o alvo novo")\n    return estacao_dia, inmet_dia, mare_dia, {k: tuple(v) for k, v in alvo.items()}\n\n\ndef carregar(destino, avisar=print):\n    banco = destino.banco\n    distrito_estacao = garantir_coordenadas(banco, avisar=avisar)\n    estacao_dia, inmet_dia, mare_dia, alvo = ler_entradas(banco, distrito_estacao)\n    linhas = montar(estacao_dia, distrito_estacao, inmet_dia, mare_dia, alvo, contexto_dos_distritos(banco))\n    agora = datetime.now(timezone.utc)\n    for l in linhas:\n        l["coletado_em"] = agora\n    destino.carregar(Carga("gold.ml_distrito_dia", linhas, chaves=("distrito_codigo", "data")))\n\n    avisar(f"{len(linhas)} linhas ({len(linhas) // 8} dias x 8 distritos)")\n    por_fonte = defaultdict(int)\n    for l in linhas:\n        por_fonte[l["fonte_chuva"] or "sem chuva"] += 1\n    avisar("chuva do dia por fonte: " + ", ".join(f"{k} {100 * v / len(linhas):.1f}%" for k, v in sorted(por_fonte.items())))\n    for ano in range(INICIO.year, FIM.year + 1):\n        do_ano = [l for l in linhas if l["ano"] == ano]\n        sem = sum(l["chuva_dia_mm"] is None for l in do_ano)\n        cem = sum(l["fonte_chuva"] == "cemaden" for l in do_ano)\n        avisar(f"  {ano}: CEMADEN {100 * cem / len(do_ano):5.1f}% | sem chuva {100 * sem / len(do_ano):5.1f}% | "\n               f"atendimentos ligados à chuva: {sum(l[\'atendimentos_chuva\'] for l in do_ano)}")\n\n\nif __name__ == "__main__":\n    carregar(obter_destino())\n',
    'etl/historico/cemaden.py': '"""Chuva histórica dos pluviômetros do CEMADEN no Recife, 2014-2024 (etapa 3b do ML).\n\nA API entrega no máximo 31 dias por estação a cada requisição, com limite de\n12 requisições por minuto: 24 estações x 132 meses = ~3.200 requisições,\numas 5 horas. Roda uma vez, de preferência à noite, e pode ser interrompida.\n\n  silver  silver.chuva_estacao_dia   uma linha por estação e dia (dia local do Recife)\n\nPor que diário e não cada leitura: 11 anos de leituras de 10 minutos passariam\nde 3 milhões de documentos (acima do plano gratuito do Atlas). O modelo usa\nchuva por dia (24 h, 72 h, 7 dias) e a maior chuva numa hora do dia (intensidade).\n\nUso:\n    python -m etl.historico.cemaden                      # 2014-01 a 2024-12, todas as estações\n    python -m etl.historico.cemaden --inicio 2020-01 --fim 2020-12\n"""\n\nimport argparse\nimport time\nfrom collections import defaultdict\nfrom datetime import date, datetime, timedelta, timezone\n\nimport requests\n\nfrom etl.comum.cemaden import FONTE, ClienteCemaden, ler_serie\nfrom etl.destinos import obter_destino\nfrom etl.destinos.base import Carga\nfrom etl.fontes.cemaden import CODIBGE_RECIFE, UF, _hora_fechada, _numero\n\nRECIFE = timezone(timedelta(hours=-3))  # o Recife não teve horário de verão de 2014 a 2024\nTABELA = "silver.chuva_estacao_dia"\nCONTROLE = "controle_historico"\nTENTATIVAS = 3\nESPERA_ERRO_S = 15  # o servidor do CEMADEN devolve erro 500 de vez em quando, sem motivo aparente\n\n\ndef meses(inicio, fim):\n    """[(ano, mes)] de inicio a fim, inclusive. inicio e fim no formato \'AAAA-MM\'."""\n    a, m = map(int, inicio.split("-"))\n    fa, fm = map(int, fim.split("-"))\n    while (a, m) <= (fa, fm):\n        yield a, m\n        a, m = (a + 1, 1) if m == 12 else (a, m + 1)\n\n\ndef por_dia(texto, codestacao, coletado_em):\n    """CSV de um mês -> uma linha por dia local: chuva total, maior chuva numa hora, nº de leituras."""\n    total, por_hora, leituras = defaultdict(float), defaultdict(float), defaultdict(int)\n    for l in ler_serie(texto):\n        valor = _numero(l.get("valor"))\n        if valor is None:\n            continue\n        dt = datetime.strptime(l["datahora"], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)\n        # a leitura das 00:10 é chuva de 00:00-00:10: recua 1 min antes de decidir o dia\n        dia = (dt - timedelta(minutes=1)).astimezone(RECIFE).date()\n        total[dia] += valor\n        leituras[dia] += 1\n        por_hora[(dia, _hora_fechada(dt))] += valor\n    maior, pico = defaultdict(float), {}\n    for (dia, hora), v in sorted(por_hora.items()):\n        if v > maior[dia]:\n            # a hora "fechada" termina às HH:00: a chuva caiu na hora anterior (início, em UTC)\n            maior[dia], pico[dia] = v, (hora - timedelta(hours=1)).replace(tzinfo=None)\n    return [{"codestacao": codestacao, "data": datetime(d.year, d.month, d.day), "ano": d.year,\n             "chuva_mm": round(total[d], 1), "max_hora_mm": round(maior[d], 1), "leituras": leituras[d],\n             "hora_pico_utc": pico.get(d), "fonte": FONTE, "coletado_em": coletado_em} for d in sorted(total)]\n\n\ndef baixar_mes(cliente, codestacao, ini, fim, espera=ESPERA_ERRO_S):\n    """CSV de um mês. Tenta de novo nos erros do servidor; devolve None se todas falharem."""\n    for tentativa in range(1, TENTATIVAS + 1):\n        try:\n            return cliente.serie_csv(codestacao, UF, ini, fim)\n        except requests.RequestException:\n            if tentativa < TENTATIVAS:\n                time.sleep(espera)\n    return None\n\n\ndef janela_do_mes(ano, mes):\n    """O mês LOCAL do Recife em UTC, no mesmo critério de por_dia().\n\n    Cada leitura é a chuva do intervalo que TERMINA no seu horário: a das 00:00 local\n    do dia 1 ainda é chuva do último dia do mês anterior. Por isso a janela começa às\n    00:01 local do dia 1 e termina às 00:00 local do dia 1 do mês seguinte (inclusive).\n    Assim cada dia local cai inteiro num único pedido, e nenhum pedido sobrescreve o\n    último dia do mês vizinho.\n    """\n    ini = datetime(ano, mes, 1, 0, 1, tzinfo=RECIFE)\n    fim = datetime(ano + (mes == 12), mes % 12 + 1, 1, tzinfo=RECIFE)\n    return ini.astimezone(timezone.utc), fim.astimezone(timezone.utc)\n\n\ndef carregar(destino, cliente, inicio, fim, so_estacao=None, avisar=print, espera=ESPERA_ERRO_S, refazer=False):\n    banco = destino.banco\n    # só o que deu certo conta como feito; mês que falhou é tentado de novo na próxima rodada.\n    # refazer: baixa de novo (por exemplo, para gravar um campo novo); marca na etiqueta do controle\n    etiqueta = "cemaden_refeito" if refazer else "cemaden"\n    feitos = {(c["codestacao"], c["mes"]) for c in banco[CONTROLE].find({"fonte": etiqueta, "status": {"$ne": "falha"}})}\n    estacoes = [e["codestacao"] for e in cliente.estacoes_do_municipio(CODIBGE_RECIFE, UF)]\n    if so_estacao:\n        estacoes = [e for e in estacoes if e == so_estacao]\n    pendentes = [(e, a, m) for e in estacoes for a, m in meses(inicio, fim) if (e, f"{a}-{m:02d}") not in feitos]\n    avisar(f"{len(estacoes)} estações, {len(pendentes)} meses pendentes "\n           f"(~{len(pendentes) * 5.5 / 3600:.1f} h pelo limite de 12 requisições/min)")\n    falhas = 0\n    for n, (codestacao, ano, mes) in enumerate(pendentes, start=1):\n        ini, fim_mes = janela_do_mes(ano, mes)\n        agora = datetime.now(timezone.utc)\n        texto = baixar_mes(cliente, codestacao, ini, fim_mes, espera)\n        chave = {"fonte": etiqueta, "codestacao": codestacao, "mes": f"{ano}-{mes:02d}"}\n        if texto is None:\n            falhas += 1\n            banco[CONTROLE].update_one(chave, {"$set": {"status": "falha", "em": agora}}, upsert=True)\n            continue\n        linhas = [l for l in por_dia(texto, codestacao, agora) if (l["data"].year, l["data"].month) == (ano, mes)]\n        if linhas:\n            destino.carregar(Carga(TABELA, linhas, chaves=("codestacao", "data")))\n        banco[CONTROLE].update_one(chave, {"$set": {"status": "ok", "dias": len(linhas), "em": agora}}, upsert=True)\n        if n % 12 == 0 or n == len(pendentes):\n            avisar(f"  {n}/{len(pendentes)}  último: {codestacao} {ano}-{mes:02d} "\n                   f"({len(linhas)} dias com leitura) | falhas até agora: {falhas}")\n    if falhas:\n        avisar(f"{falhas} meses falharam por erro do servidor do CEMADEN. Rode o mesmo comando de novo "\n               "para tentar só esses.")\n\n\ndef main():\n    p = argparse.ArgumentParser(description="Carga histórica do CEMADEN (retomável).")\n    p.add_argument("--inicio", default="2014-01")\n    p.add_argument("--fim", default="2024-12")\n    p.add_argument("--estacao", help="só uma estação (código), para testar")\n    p.add_argument("--refazer", action="store_true",\n                   help="baixa de novo todos os meses (retomável à parte), para gravar campos novos")\n    a = p.parse_args()\n    try:\n        carregar(obter_destino(), ClienteCemaden(), a.inicio, a.fim, a.estacao, lambda s: print(s, flush=True),\n                 refazer=a.refazer)\n    except KeyboardInterrupt:\n        print("\\nInterrompido. Rode o mesmo comando para continuar de onde parou.")\n\n\nif __name__ == "__main__":\n    main()\n',
    'etl/historico/inmet.py': '"""Chuva histórica da estação automática do INMET no Recife (A301), 2014-2024 (etapa 3b do ML).\n\nFonte: pacotes anuais abertos do INMET (portal.inmet.gov.br/dadoshistoricos),\num ZIP por ano com um CSV por estação do Brasil. Baixa o ano, guarda só a\nestação do Recife e descarta o resto. Sem cadastro, sem token.\n\n  silver  silver.chuva_inmet_dia   uma linha por dia local do Recife\n\nServe para conferir o CEMADEN e para preencher os dias em que os pluviômetros\nainda não existiam ou estavam parados. Os CSVs mudam de formato entre os anos\n(data com / ou -, hora "0000" ou "0000 UTC", vírgula decimal, -9999 = sem dado):\na leitura cobre todos esses casos.\n\nUso:\n    python -m etl.historico.inmet                 # 2014 a 2024\n    python -m etl.historico.inmet --inicio 2024 --fim 2024\n"""\n\nimport argparse\nimport csv\nimport io\nimport re\nimport zipfile\nfrom collections import defaultdict\nfrom datetime import datetime, timedelta, timezone\n\nfrom etl.comum.http import get_bytes\nfrom etl.comum.tabela import decodificar\nfrom etl.destinos import obter_destino\nfrom etl.destinos.base import Carga\n\nURL = "https://portal.inmet.gov.br/uploads/dadoshistoricos/{ano}.zip"\nESTACAO = "A301"  # Recife (automática)\nRECIFE = timezone(timedelta(hours=-3))\nTABELA = "silver.chuva_inmet_dia"\nCONTROLE = "controle_historico"\nFONTE = "INMET, estação automática A301 Recife"\n\n\ndef csv_da_estacao(conteudo_zip, estacao=ESTACAO):\n    """O texto do CSV da estação dentro do ZIP do ano; None se não houver."""\n    with zipfile.ZipFile(io.BytesIO(conteudo_zip)) as z:\n        nome = next((n for n in z.namelist() if f"_{estacao}_" in n.upper()), None)\n        return decodificar(z.read(nome)) if nome else None\n\n\ndef _numero(v):\n    try:\n        x = float(str(v).strip().replace(",", "."))\n    except ValueError:\n        return None\n    return None if x <= -9999 else x\n\n\ndef _quando(data, hora):\n    """\'2014/01/01\' ou \'2019-01-01\' + \'1200\' ou \'1200 UTC\' ou \'12:00\' -> datetime UTC."""\n    d = datetime.strptime(data.strip().replace("/", "-"), "%Y-%m-%d")\n    h = re.sub(r"\\D", "", hora)[:4].ljust(4, "0")\n    return d.replace(hour=int(h[:2]), minute=int(h[2:]), tzinfo=timezone.utc)\n\n\ndef por_dia(texto, coletado_em):\n    """CSV horário do INMET -> uma linha por dia local: total, maior hora, horas com dado."""\n    linhas = texto.splitlines()\n    # o cabeçalho é a linha com a coluna de chuva (antes dela há metadados, como "DATA DE FUNDACAO")\n    ini = next((i for i, l in enumerate(linhas) if "PRECIPITA" in l.upper()), None)\n    if ini is None:\n        return []\n    leitor = csv.reader(linhas[ini + 1:], delimiter=";")\n    cab = [c.strip().upper() for c in linhas[ini].split(";")]\n    c_data, c_hora = 0, 1\n    c_chuva = next(i for i, c in enumerate(cab) if c.startswith("PRECIPITA"))\n    total, maior, horas, pico = defaultdict(float), defaultdict(float), defaultdict(int), {}\n    for l in leitor:\n        if len(l) <= c_chuva or not l[c_data].strip():\n            continue\n        valor = _numero(l[c_chuva])\n        if valor is None:\n            continue\n        # a hora registrada é o FIM do intervalo: a chuva das 00 UTC é da hora anterior\n        quando = _quando(l[c_data], l[c_hora])\n        dia = (quando - timedelta(minutes=1)).astimezone(RECIFE).date()\n        total[dia] += valor\n        if valor > maior[dia] or dia not in pico:\n            # a leitura fecha a hora: a chuva caiu na hora ANTERIOR (início do intervalo, em UTC)\n            pico[dia] = (quando - timedelta(hours=1)).replace(tzinfo=None) if valor > 0 else None\n        maior[dia] = max(maior[dia], valor)\n        horas[dia] += 1\n    return [{"data": datetime(d.year, d.month, d.day), "ano": d.year, "chuva_mm": round(total[d], 1),\n             "max_hora_mm": round(maior[d], 1), "horas_com_dado": horas[d], "hora_pico_utc": pico.get(d),\n             "fonte": FONTE,\n             "coletado_em": coletado_em} for d in sorted(total)]\n\n\ndef carregar(destino, inicio, fim, baixar=lambda ano: get_bytes(URL.format(ano=ano), timeout=600), avisar=print,\n             refazer=False):\n    banco = destino.banco\n    feitos = set() if refazer else {c["mes"] for c in banco[CONTROLE].find({"fonte": "inmet"})}\n    for ano in range(inicio, fim + 1):\n        if str(ano) in feitos:\n            avisar(f"  {ano}: já carregado")\n            continue\n        avisar(f"  {ano}: baixando o pacote do ano (arquivo grande, alguns minutos)...")\n        agora = datetime.now(timezone.utc)\n        texto = csv_da_estacao(baixar(ano))\n        # o pacote é do ano em UTC: as 3 primeiras horas dele são a noite de 31/12 do ano anterior\n        # no Recife. Ficam de fora para não apagar aquele dia (já gravado com as outras 21 horas).\n        linhas = [l for l in por_dia(texto, agora) if l["ano"] == ano] if texto else []\n        if linhas:\n            destino.carregar(Carga(TABELA, linhas, chaves=("data",)))\n        banco[CONTROLE].update_one({"fonte": "inmet", "mes": str(ano)},\n                                   {"$set": {"dias": len(linhas), "em": agora}}, upsert=True)\n        completos = sum(l["horas_com_dado"] >= 20 for l in linhas)\n        motivo = (f" | estação {ESTACAO} não está no pacote deste ano" if not texto\n                  else " | a estação está no pacote, mas sem nenhum valor de chuva" if not linhas else "")\n        avisar(f"  {ano}: {len(linhas)} dias com dado ({completos} com 20 h ou mais){motivo}")\n\n\ndef main():\n    p = argparse.ArgumentParser(description="Carga histórica do INMET (retomável, por ano).")\n    p.add_argument("--inicio", type=int, default=2014)\n    p.add_argument("--fim", type=int, default=2024)\n    p.add_argument("--refazer", action="store_true", help="baixa de novo mesmo os anos já carregados")\n    a = p.parse_args()\n    try:\n        carregar(obter_destino(), a.inicio, a.fim, avisar=lambda s: print(s, flush=True), refazer=a.refazer)\n    except KeyboardInterrupt:\n        print("\\nInterrompido. Rode o mesmo comando para continuar de onde parou.")\n\n\nif __name__ == "__main__":\n    main()\n',
    'etl/historico/mare.py': '"""Maré histórica do Recife, 2014-2024, calculada pela astronomia (etapa 3c do ML).\n\nNão há medição pública e contínua de maré no Recife nesse período: o marégrafo\nhistórico (PSMSL 556) parou em 1968, e nem o CEMADEN nem o INMET medem nível do\nmar ou de rio dentro da cidade (decisão 009). Mas a maré é quase toda\nastronômica: segue ciclos da Lua e do Sol que se repetem.\n\nMétodo (análise harmônica, biblioteca utide):\n  1. baixa os últimos 92 dias de nível do mar do Open-Meteo Marine (o máximo da API)\n  2. ajusta as componentes de maré (M2, S2, N2, K1, O1...) a essa série\n  3. recalcula o nível hora a hora de 2014 a 2024 com essas componentes\n  4. resume por dia local: maré máxima, mínima e amplitude\n\n  silver  silver.mare_calculada_dia   uma linha por dia\n  silver  silver.mare_calculada_hora  o nível hora a hora (UTC), para saber a maré NA HORA da chuva\n\nLimitação: não inclui ressaca (vento e pressão). Cobre o que mais importa para\nalagamento: saber se a chuva caiu em maré de sizígia (as cheias mais altas).\nOs níveis são relativos ao nível médio do mar, não ao zero da tábua de marés.\n\nUso:\n    python -m etl.historico.mare\n"""\n\nimport argparse\nfrom datetime import datetime, timedelta, timezone\n\nimport numpy as np\n\nfrom etl.comum.http import get_json\nfrom etl.destinos import obter_destino\nfrom etl.destinos.base import Carga\nfrom etl.fontes.mare import LATITUDE, LONGITUDE, URL\n\nRECIFE = timezone(timedelta(hours=-3))\nTABELA = "silver.mare_calculada_dia"\nFONTE = "Maré astronômica calculada (utide) a partir do Open-Meteo Marine"\nDIAS_AJUSTE = 92\n\n\ndef serie_recente():\n    """(horas UTC como datetime64, níveis) dos últimos DIAS_AJUSTE dias, sem as horas vazias."""\n    r = get_json(URL, {"latitude": LATITUDE, "longitude": LONGITUDE, "cell_selection": "sea",\n                       "hourly": "sea_level_height_msl", "past_days": DIAS_AJUSTE, "forecast_days": 1,\n                       "timeformat": "unixtime", "timezone": "GMT"})\n    pares = [(t, v) for t, v in zip(r["hourly"]["time"], r["hourly"]["sea_level_height_msl"]) if v is not None]\n    tempos = np.array([np.datetime64(int(t), "s") for t, _ in pares])\n    return tempos, np.array([v for _, v in pares], dtype=float)\n\n\ndef ajustar(tempos, niveis):\n    """Componentes harmônicas da maré local. Devolve (coef, erro médio do ajuste em metros)."""\n    import utide\n    coef = utide.solve(tempos, niveis, lat=LATITUDE, method="ols", conf_int="none", verbose=False)\n    refeito = utide.reconstruct(tempos, coef, verbose=False).h\n    return coef, float(np.sqrt(np.mean((refeito - niveis) ** 2)))\n\n\ndef serie_horaria(coef, inicio, fim):\n    """[(hora UTC sem fuso, nível)] de inicio a fim (datas locais do Recife)."""\n    import utide\n    ini = datetime(inicio.year, inicio.month, inicio.day, tzinfo=RECIFE).astimezone(timezone.utc)\n    horas = int(((fim - inicio).days + 1) * 24)\n    tempos = np.array([np.datetime64(ini.replace(tzinfo=None) + timedelta(hours=h)) for h in range(horas)])\n    nivel = utide.reconstruct(tempos, coef, verbose=False).h\n    return [(t.astype(datetime), float(v)) for t, v in zip(tempos, nivel)]\n\n\ndef por_dia(horarios, coletado_em):\n    """Série horária resumida por dia local do Recife: máxima, mínima e amplitude."""\n    dias = {}\n    for t, v in horarios:\n        dia = t.replace(tzinfo=timezone.utc).astimezone(RECIFE).date()\n        dias.setdefault(dia, []).append(v)\n    return [{"data": datetime(d.year, d.month, d.day), "ano": d.year,\n             "mare_max_m": round(max(v), 3), "mare_min_m": round(min(v), 3),\n             "amplitude_m": round(max(v) - min(v), 3), "fonte": FONTE, "coletado_em": coletado_em}\n            for d, v in sorted(dias.items())]\n\n\ndef carregar(destino, inicio, fim, serie=serie_recente, avisar=print):\n    tempos, niveis = serie()\n    avisar(f"série para o ajuste: {len(niveis)} horas ({len(niveis) / 24:.0f} dias)")\n    if len(niveis) < 24 * 30:\n        raise ValueError("menos de 30 dias de série: o ajuste das componentes ficaria impreciso")\n    coef, erro = ajustar(tempos, niveis)\n    principais = sorted(zip(coef.name, coef.A), key=lambda c: -c[1])[:5]\n    avisar("componentes principais (amplitude em m): " + ", ".join(f"{n} {a:.2f}" for n, a in principais))\n    avisar(f"erro médio do ajuste na série recente: {erro:.2f} m (inclui o que não é maré: vento, pressão)")\n    agora = datetime.now(timezone.utc)\n    horarios = serie_horaria(coef, inicio, fim)\n    linhas = por_dia(horarios, agora)\n    destino.carregar(Carga(TABELA, linhas, chaves=("data",)))\n    destino.carregar(Carga("silver.mare_calculada_hora",\n                           [{"hora": h, "nivel_m": round(v, 3), "fonte": FONTE, "coletado_em": agora}\n                            for h, v in horarios], chaves=("hora",)))\n    amplitudes = sorted(l["amplitude_m"] for l in linhas)\n    avisar(f"{len(linhas)} dias gravados | amplitude diária de {amplitudes[0]:.2f} a {amplitudes[-1]:.2f} m")\n\n\ndef main():\n    p = argparse.ArgumentParser(description="Maré histórica calculada (análise harmônica).")\n    p.add_argument("--inicio", default="2014-01-01")\n    p.add_argument("--fim", default="2024-12-31")\n    a = p.parse_args()\n    para_data = lambda s: datetime.strptime(s, "%Y-%m-%d").date()\n    carregar(obter_destino(), para_data(a.inicio), para_data(a.fim), avisar=lambda s: print(s, flush=True))\n\n\nif __name__ == "__main__":\n    main()\n',
    'ml/experimento_mare.py': '"""A maré agrava o alagamento? Teste com e sem maré, no mesmo método do controle sem chuva.\n\nAlvo: houve alagamento registrado pela Defesa Civil no distrito, no dia ou no seguinte\n(o registro pode atrasar um dia). Só os distritos de planície (DS I, IV, V, VI), onde a\nmaré pode represar os canais.\n\n  A. ESCALA DIÁRIA (2015-2024): nível máximo do mar no dia e ressaca (GTSM) e amplitude\n     da maré. Treino 2015-2020 | limiar em 2021 | teste 2022-2024.\n  B. NA HORA DA CHUVA (2015-2024): o nível da maré NA HORA do pico de chuva do distrito\n     (pluviômetro do CEMADEN com a hora mais forte + maré calculada hora a hora). É a\n     hipótese física: a chuva forte caindo na preamar. Mesma divisão do A.\n     (A primeira versão usava o INMET, 2015-2021: o teste teve só 8 dias com alagamento.)\n\nRegra fixada ANTES de rodar com os dados reais: a maré tem efeito se o modelo COM maré\nsuperar o modelo SEM maré em pelo menos 0,02 de PRECISÃO MÉDIA (average precision) no teste.\nA precisão média mede se a maré traz informação, em qualquer limiar; o F1 depende do limiar\nescolhido pela meta de 80% de recall, que nos testes empatava os dois modelos mesmo quando\na maré mudava muito a qualidade da previsão. O F1 é mostrado, mas não decide.\n\nUso:\n    python -m ml.experimento_mare\n"""\n\nfrom pathlib import Path\n\nimport pandas as pd\nfrom sklearn.metrics import average_precision_score\n\nfrom etl.destinos import obter_destino\nfrom ml import dados, metricas\nfrom ml.modelo import ModeloRisco, matriz\n\nSAIDA = Path(__file__).resolve().parents[1] / "analises" / "ml" / "saida"\nBASE = ["chuva_dia_mm", "chuva_vespera_mm", "chuva_3d_mm", "chuva_7d_mm", "acumulado_72h_antes", "max_hora_mm",\n        "mes", "distrito_codigo"]\nMARGEM = 0.02\nEXPERIMENTOS = {\n    "A": {"titulo": "escala diária (GTSM)", "mar": ["nivel_total_max_m", "ressaca_max_m", "mare_amplitude_m"],\n          "treino": range(2015, 2020), "validacao": 2020 + 1, "teste": range(2022, 2025)},\n    "B": {"titulo": "maré na hora do pico de chuva (CEMADEN por distrito + maré horária)",\n          "mar": ["mare_hora_pico_m", "chuva_pico_mm"],\n          "treino": range(2015, 2020), "validacao": 2020 + 1, "teste": range(2022, 2025)},\n}\n\n\ndef montar(tabela, gtsm, mare_hora):\n    """Junta tudo por dia e marca o alvo (alagamento em D ou D+1)."""\n    df = tabela[tabela["distrito_codigo"].isin(dados.DISTRITOS_PLANICIE)].copy()\n    df["dia"] = pd.to_datetime(df["data"]).dt.normalize()\n    df = df.sort_values(["distrito_codigo", "dia"])\n    seguinte = df.groupby("distrito_codigo")["atendimentos_alagamento"].shift(-1).fillna(0)\n    df["critico"] = (df["atendimentos_alagamento"].fillna(0) + seguinte) > 0\n    if not gtsm.empty:\n        gtsm = gtsm.assign(dia=pd.to_datetime(gtsm["data"]).dt.normalize())\n        df = df.merge(gtsm[["dia", "nivel_total_max_m", "ressaca_max_m"]], on="dia", how="left")\n    if "hora_pico_utc" in df and not mare_hora.empty:\n        nivel = dict(zip(pd.to_datetime(mare_hora["hora"]), mare_hora["nivel_m"]))\n        df["mare_hora_pico_m"] = pd.to_datetime(df["hora_pico_utc"]).dt.floor("h").map(nivel)\n    return df\n\n\ndef rodar(df, cfg, grade=None, avisar=print):\n    colunas = BASE + cfg["mar"]\n    if not set(cfg["mar"]) <= set(df.columns) or df[cfg["mar"][0]].notna().sum() == 0:\n        avisar("   sem os dados deste experimento (veja o passo a passo no docstring)")\n        return None\n    d = df[df["ano"].isin(list(cfg["treino"]) + [cfg["validacao"]] + list(cfg["teste"]))].dropna(subset=cfg["mar"])\n    d = d.sort_values("dia")\n    sub, val = d[d["ano"].isin(cfg["treino"])], d[d["ano"] == cfg["validacao"]]\n    treino, teste = d[d["ano"] <= cfg["validacao"]], d[d["ano"].isin(cfg["teste"])]\n    avisar(f"   treino {len(treino)} linhas ({int(treino[\'critico\'].sum())} com alagamento) | "\n           f"teste {len(teste)} ({int(teste[\'critico\'].sum())} com alagamento)")\n    resultado = {}\n    for nome, entradas in (("com maré", colunas), ("sem maré", BASE)):\n        m = ModeloRisco("xgboost", grade, entradas)\n        m.otimizar(matriz(treino, entradas), treino["critico"])\n        m.escolher_limiar(matriz(sub, entradas), sub["critico"], matriz(val, entradas), val["critico"])\n        m.treinar(matriz(treino, entradas), treino["critico"])\n        r = metricas.resumo(teste["critico"], m.prever(matriz(teste, entradas)))\n        r["ap"] = round(float(average_precision_score(teste["critico"], m.probabilidade(matriz(teste, entradas)))), 3)\n        resultado[nome] = (r, m)\n        avisar("   " + metricas.texto(nome, r) + f" | precisão média {r[\'ap\']:.3f}")\n    com, sem = resultado["com maré"][0], resultado["sem maré"][0]\n    efeito = com["ap"] >= sem["ap"] + MARGEM\n    imp = resultado["com maré"][1].importancia()\n    avisar("   importância (com maré): " + ", ".join(f"{k} {v:.2f}" for k, v in list(imp.items())[:6]))\n    avisar(f"   VEREDITO {\'A MARÉ TEM EFEITO\' if efeito else \'SEM EFEITO DA MARÉ\'}: precisão média "\n           f"{com[\'ap\']:.3f} com maré x {sem[\'ap\']:.3f} sem ({com[\'ap\'] - sem[\'ap\']:+.3f}) | F1 {com[\'f1\']:.2f} x {sem[\'f1\']:.2f}")\n    return efeito\n\n\ndef executar(banco, grade=None, avisar=print):\n    tabela = pd.DataFrame(list(banco["gold_ml_distrito_dia"].find({"ano": {"$gte": 2015}}, {"_id": 0, "coletado_em": 0})))\n    tabela = dados.preparar(tabela)\n    gtsm = pd.DataFrame(list(banco["silver_mare_gtsm_dia"].find({}, {"_id": 0, "data": 1, "nivel_total_max_m": 1,\n                                                                      "ressaca_max_m": 1})))\n    mare_hora = pd.DataFrame(list(banco["silver_mare_calculada_hora"].find({}, {"_id": 0, "hora": 1, "nivel_m": 1})))\n    df = montar(tabela, gtsm, mare_hora)\n    vereditos = {}\n    for chave, cfg in EXPERIMENTOS.items():\n        avisar(f"\\nExperimento {chave}: {cfg[\'titulo\']}")\n        vereditos[chave] = rodar(df, cfg, grade, avisar)\n    return vereditos\n\n\ndef main():\n    SAIDA.mkdir(parents=True, exist_ok=True)\n    linhas = []\n\n    def avisar(s):\n        print(s, flush=True)\n        linhas.append(s)\n    executar(obter_destino().banco, avisar=avisar)\n    (SAIDA / "experimento_mare.txt").write_text("\\n".join(linhas), encoding="utf-8")\n\n\nif __name__ == "__main__":\n    main()\n',
    'tests/test_experimento_mare.py': 'import math\nimport random\nfrom datetime import datetime, timedelta\n\nimport pandas as pd\n\nfrom ml import experimento_mare as em\n\nGRADE = {"n_estimators": [60], "max_depth": [3], "learning_rate": [0.1]}\n\n\ndef _dados(mare_importa):\n    """Alagamento quando chove forte E (se mare_importa) a maré na hora do pico está alta."""\n    random.seed(3)\n    tabela, gtsm, horas = [], [], []\n    d = datetime(2015, 1, 1)\n    while d <= datetime(2024, 12, 31):\n        chuva = max(0.0, random.gauss(6, 14))\n        pico = d + timedelta(hours=random.randint(0, 23))\n        nivel = 1.2 + 1.0 * math.cos(2 * math.pi * (pico - datetime(2015, 1, 1)).total_seconds() / 3600 / 12.42)\n        horas.append({"hora": pico.replace(minute=0), "nivel_m": nivel})\n        alaga = chuva > 25 and (nivel > 1.6 or not mare_importa) and random.random() < 0.9\n        gtsm.append({"data": d, "nivel_total_max_m": 2.2 + random.gauss(0, .05), "ressaca_max_m": abs(random.gauss(.08, .02))})\n        for dist in (1, 6):\n            tabela.append({"distrito_codigo": dist, "data": d, "ano": d.year, "mes": d.month, "chuva_dia_mm": chuva,\n                           "hora_pico_utc": pico, "chuva_pico_mm": chuva / 3,\n                           "chuva_vespera_mm": None, "chuva_3d_mm": chuva, "chuva_7d_mm": None, "max_hora_mm": chuva / 3,\n                           "mare_max_m": 2.2, "mare_amplitude_m": 2.0, "atendimentos_alagamento": int(alaga),\n                           "atendimentos_chuva": 0})\n        d += timedelta(1)\n    tab = em.dados.preparar(pd.DataFrame(tabela))\n    return em.montar(tab, pd.DataFrame(gtsm), pd.DataFrame(horas))\n\n\ndef test_detecta_a_mare_na_hora_da_chuva_quando_ela_importa():\n    df = _dados(mare_importa=True)\n    assert em.rodar(df, em.EXPERIMENTOS["B"], GRADE, avisar=lambda s: None) is True\n\n\ndef test_nao_inventa_efeito_quando_a_mare_nao_importa():\n    df = _dados(mare_importa=False)\n    assert em.rodar(df, em.EXPERIMENTOS["B"], GRADE, avisar=lambda s: None) is False\n',
    'tests/test_historico_cemaden.py': 'from datetime import datetime\n\nfrom etl.historico import cemaden as hist\n\nCAB = "OBS.: PCD com horario UTC!\\ncod.estacao;nome;municipio;uf;latitude;longitude;datahora;sensor;valor;qualificacao;offset"\n\n\ndef _csv(linhas):\n    return "\\n".join([CAB, *[f"A;X;RECIFE;PE;-8;-34.9;{dt};chuva;{v};0000;" for dt, v in linhas]])\n\n\nclass Cliente:\n    def __init__(self):\n        self.pedidos = []\n\n    def estacoes_do_municipio(self, codibge, uf):\n        return [{"codestacao": "A"}, {"codestacao": "B"}]\n\n    def serie_csv(self, codigo, uf, inicio, fim):\n        self.pedidos.append((codigo, inicio.strftime("%Y-%m")))\n        if codigo == "B":\n            return ""  # estação ainda não existia\n        return _csv([("2014-01-01 12:10:00", 2.0), ("2014-01-01 12:50:00", 3.0), ("2014-01-01 15:00:00", 1.0),\n                     ("2014-01-02 02:30:00", 4.0)])  # 23:30 do dia 1 no Recife\n\n\ndef test_dia_local_total_e_intensidade():\n    linhas = {l["data"].day: l for l in hist.por_dia(_csv([("2014-01-01 12:10:00", 2.0), ("2014-01-01 12:50:00", 3.0),\n                                                            ("2014-01-02 02:30:00", 4.0)]), "A", None)}\n    assert (linhas[1]["chuva_mm"], linhas[1]["max_hora_mm"]) == (9.0, 5.0)   # 02:30 UTC ainda é dia 1 no Recife\n    assert linhas[1]["hora_pico_utc"] == datetime(2014, 1, 1, 12)            # 12:10 e 12:50 caíram entre 12h e 13h\n    assert 2 not in linhas\n\n\ndef test_carga_retoma_de_onde_parou(destino):\n    c = Cliente()\n    hist.carregar(destino, c, "2014-01", "2014-02", avisar=lambda s: None, espera=0)\n    assert len(c.pedidos) == 4\n    c2 = Cliente()\n    hist.carregar(destino, c2, "2014-01", "2014-03", avisar=lambda s: None, espera=0)\n    assert c2.pedidos == [("A", "2014-03"), ("B", "2014-03")]              # só o mês novo\n    assert destino.banco["silver_chuva_estacao_dia"].count_documents({}) == 1   # upsert: não duplica\n\n\nclass ClienteInstavel(Cliente):\n    """O servidor do CEMADEN às vezes devolve erro 500: aqui, sempre no mês de fevereiro."""\n    def serie_csv(self, codigo, uf, inicio, fim):\n        if inicio.month == 2:\n            self.pedidos.append((codigo, inicio.strftime("%Y-%m")))\n            raise hist.requests.HTTPError("500")\n        return super().serie_csv(codigo, uf, inicio, fim)\n\n\ndef test_mes_com_erro_nao_derruba_a_carga_e_volta_na_proxima(destino):\n    c = ClienteInstavel()\n    hist.carregar(destino, c, "2014-01", "2014-02", avisar=lambda s: None, espera=0)\n    falhas = destino.banco["controle_historico"].count_documents({"status": "falha"})\n    assert falhas == 2 and c.pedidos.count(("A", "2014-02")) == hist.TENTATIVAS\n    c2 = Cliente()\n    hist.carregar(destino, c2, "2014-01", "2014-02", avisar=lambda s: None, espera=0)\n    assert c2.pedidos == [("A", "2014-02"), ("B", "2014-02")]   # só os que falharam\n\n\ndef test_janela_e_o_mes_local():\n    from datetime import datetime, timezone\n    ini, fim = hist.janela_do_mes(2014, 12)\n    assert ini == datetime(2014, 12, 1, 3, 1, tzinfo=timezone.utc)\n    assert fim == datetime(2015, 1, 1, 3, 0, tzinfo=timezone.utc)   # a leitura das 00:00 local de 01/01 é do dia 31\n\n\ndef test_leitura_da_meia_noite_nao_sobrescreve_o_mes_anterior(destino):\n    class Cliente2(Cliente):\n        def estacoes_do_municipio(self, codibge, uf):\n            return [{"codestacao": "A"}]\n\n        def serie_csv(self, codigo, uf, inicio, fim):\n            if inicio.month == 1:   # janeiro: chuva no dia 31 às 20h local, e a leitura da meia-noite de 01/02\n                return _csv([("2014-01-31 23:00:00", 8.0), ("2014-02-01 03:00:00", 1.0)])\n            return _csv([("2014-02-01 03:00:00", 1.0), ("2014-02-02 15:00:00", 2.0)])  # a API repete a borda\n    hist.carregar(destino, Cliente2(), "2014-01", "2014-02", avisar=lambda s: None, espera=0)\n    dias = {d["data"].strftime("%m-%d"): d["chuva_mm"] for d in destino.banco["silver_chuva_estacao_dia"].find()}\n    assert dias == {"01-31": 9.0, "02-02": 2.0}\n\n\ndef test_refazer_baixa_de_novo_e_tem_controle_proprio(destino):\n    c = Cliente()\n    hist.carregar(destino, c, "2014-01", "2014-01", avisar=lambda s: None, espera=0)\n    c2 = Cliente()\n    hist.carregar(destino, c2, "2014-01", "2014-01", avisar=lambda s: None, espera=0, refazer=True)\n    assert len(c2.pedidos) == 2                                    # baixou de novo\n    c3 = Cliente()\n    hist.carregar(destino, c3, "2014-01", "2014-01", avisar=lambda s: None, espera=0, refazer=True)\n    assert c3.pedidos == []                                        # e a refeita também retoma\n',
    'tests/test_historico_mare.py': 'from datetime import date\n\nimport numpy as np\nimport pytest\n\nfrom etl.historico import mare\n\npytest.importorskip("utide")\n\n\ndef _serie_sintetica():\n    """92 dias de uma maré com M2 de 0,8 m e S2 de 0,3 m: a soma vai de ~0,5 m (quadratura) a ~1,1 m (sizígia)."""\n    tempos = np.arange(np.datetime64("2026-08-01T00"), np.datetime64("2026-11-01T00"), np.timedelta64(1, "h"))\n    h = np.arange(len(tempos))\n    return tempos, 0.8 * np.cos(2 * np.pi * h / 12.4206) + 0.3 * np.cos(2 * np.pi * h / 12.0)\n\n\ndef test_ajuste_recupera_as_componentes():\n    coef, erro = mare.ajustar(*_serie_sintetica())\n    amp = dict(zip(coef.name, coef.A))\n    assert abs(amp["M2"] - 0.8) < 0.05 and abs(amp["S2"] - 0.3) < 0.05 and erro < 0.05\n\n\ndef test_historico_diario_tem_sizigia_e_quadratura(destino):\n    mare.carregar(destino, date(2014, 1, 1), date(2014, 1, 31), serie=_serie_sintetica, avisar=lambda s: None)\n    dias = list(destino.banco["silver_mare_calculada_dia"].find())\n    assert len(dias) == 31\n    maximos = [d["mare_max_m"] for d in dias]\n    assert max(maximos) > 1.0 and min(maximos) < 0.7      # o ciclo de ~15 dias aparece no histórico\n    assert destino.banco["silver_mare_calculada_hora"].count_documents({}) == 31 * 24\n\n\ndef test_serie_curta_demais_e_recusada(destino):\n    curta = lambda: (_serie_sintetica()[0][:200], _serie_sintetica()[1][:200])\n    with pytest.raises(ValueError):\n        mare.carregar(destino, date(2014, 1, 1), date(2014, 1, 2), serie=curta, avisar=lambda s: None)\n',
    'tests/test_ml_distrito_dia.py': 'from datetime import date, timedelta\n\nfrom dominio.feriados import feriados_recife\nfrom etl.derivados import ml_distrito_dia as ml\n\nD0 = date(2019, 6, 10)\n\n\ndef _montar(estacao_dia, inmet=None, alvo=None):\n    return ml.montar(estacao_dia, {"A": 3, "B": 3, "C": 6}, inmet or {}, {D0: (1.1, 2.2)}, alvo or {},\n                     {3: {"comunidades": 40}}, D0, D0 + timedelta(2))\n\n\ndef test_pior_estacao_valida_e_acumulados():\n    estacao = {}\n    for n in range(-7, 3):\n        dia = D0 + timedelta(n)\n        estacao[("A", dia)] = (10.0, 3.0, 24)\n        estacao[("B", dia)] = (30.0, 9.0, 5)        # poucas leituras: não conta, mesmo sendo maior\n    linhas = {(l["distrito_codigo"], l["data"].date()): l for l in _montar(estacao)}\n    l = linhas[(3, D0)]\n    assert (l["chuva_dia_mm"], l["chuva_3d_mm"], l["chuva_7d_mm"], l["fonte_chuva"]) == (10.0, 30.0, 70.0, "cemaden")\n    assert (l["mare_max_m"], l["comunidades"]) == (1.1, 40)\n    assert linhas[(5, D0)]["chuva_dia_mm"] is None                  # distrito sem estação e sem INMET\n\n\ndef test_inmet_cobre_o_distrito_sem_estacao_valida():\n    inmet = {D0 + timedelta(n): (4.0, 1.0, 24) for n in range(-7, 3)}\n    l = {(x["distrito_codigo"], x["data"].date()): x for x in _montar({}, inmet)}[(5, D0)]\n    assert (l["chuva_dia_mm"], l["fonte_chuva"]) == (4.0, "inmet")\n\n\ndef test_alvo_contexto_e_calendario():\n    linhas = _montar({}, alvo={(3, D0): (12, 20, 4, 6)})\n    l = next(x for x in linhas if x["distrito_codigo"] == 3 and x["data"].date() == D0)\n    assert (l["atendimentos_chuva"], l["atendimentos_reativos"]) == (12, 20)\n    assert (l["atendimentos_alagamento"], l["atendimentos_deslizamento"]) == (4, 6)\n    assert len(linhas) == 8 * 3 and l["dia_semana"] == 0 and not l["pandemia"]\n\n\ndef test_feriados_do_recife():\n    f = feriados_recife(2024)\n    assert date(2024, 2, 12) in f and date(2024, 2, 13) in f        # carnaval de 2024\n    assert date(2024, 6, 24) in f and date(2024, 7, 16) in f and date(2024, 12, 25) in f\n\n\n\ndef test_hora_do_pico_vem_da_estacao_com_a_hora_mais_forte():\n    from datetime import datetime\n    estacao = {("A", D0): (40.0, 8.0, 24, datetime(2019, 6, 10, 15)), ("B", D0): (30.0, 20.0, 24, datetime(2019, 6, 10, 9))}\n    l = {(x["distrito_codigo"], x["data"].date()): x for x in _montar(estacao)}[(3, D0)]\n    assert (l["chuva_dia_mm"], l["chuva_pico_mm"], l["hora_pico_utc"]) == (40.0, 20.0, datetime(2019, 6, 10, 9))\n',
}
